    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def minimumPairRemoval(self, nums: List[int]) -> int:\n        count = 0\n\n        while len(nums) > 1:\n            isAscending = True\n            minSum = float(\"inf\")\n            targetIndex = -1\n\n            for i in range(len(nums) - 1):\n                pair_sum = nums[i] + nums[i + 1]\n\n                if nums[i] > nums[i + 1]:\n                    isAscending = False\n\n                if pair_sum < minSum:\n                    minSum = pair_sum\n                    targetIndex = i\n\n            if isAscending:\n                break\n\n            count += 1\n            nums[targetIndex] = minSum\n            nums.pop(targetIndex + 1)\n\n        return count\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.minimumPairRemoval(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
